const todayISO = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const catIcons={'Comida':'◒','Transporte':'↗','Hogar':'⌂','Servicios':'ϟ','Entretenimiento':'♫','Salud':'＋','Otros':'◇','Educación':'▤','Ropa':'◇','Mascotas':'♧','Deudas':'↔'};
const state={gastos:[],categories:[],config:{},alerts:[],notifications:[],dashboard:{},presupuestos:{mensual:0,categorias:{}},metas:[],cierres:[],view:'dashboard',report:'daily',editing:null,reportData:null};
const STORE_KEY='gestor_gastos_edwin_v1';
const TRACKING_START_DEFAULT='2026-10-15';
const DEFAULT_CONFIG={...(window.GESTOR_INITIAL?.config||{porcentaje_alerta_diaria:50,porcentaje_alerta_semanal:40,limites_categoria:{}}),fecha_inicio_control:TRACKING_START_DEFAULT};
function safeGet(key){try{return localStorage.getItem(key)}catch(e){return null}}
