      gastos:x.gastos.map((g,i)=>({...(g&&typeof g==='object'?g:{}),id:Number(g?.id)||i+1,monto:Number(g?.monto)||0,categoria:String(g?.categoria||'Otros'),descripcion:String(g?.descripcion||''),fecha:String(g?.fecha||''),tipo:g?.tipo==='ingreso'?'ingreso':'gasto'})),
