function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),3600)}
function addNotification(title,message,type='info'){const item={id:Date.now()+Math.floor(Math.random()*1000),title:String(title),message:String(message),type,fecha:new Date().toISOString(),leida:false};localDB.notifications=Array.isArray(localDB.notifications)?localDB.notifications:[];localDB.notifications.unshift(item);localDB.notifications=localDB.notifications.slice(0,100);state.notifications=localDB.notifications;persist();updateNotificationBadge();if(state.view==='notifications')renderNotifications();return item}
function updateNotificationBadge(){const list=localDB.notifications||[],unread=list.filter(n=>!n.leida).length,badge=$('#notificationBadge');if(badge){badge.textContent=unread>99?'99+':String(unread);badge.hidden=unread===0}const tag=$('#notificationUnreadTag');if(tag)tag.textContent=`${unread} PENDIENTES`}
