async function passwordDigest(value){
  const data=new TextEncoder().encode(String(value));
  if(window.crypto&&crypto.subtle){const hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
  // Compatibilidad con navegadores que no exponen Web Crypto al abrir el archivo directamente.
  let h=2166136261;for(const b of data){h^=b;h=Math.imul(h,16777619)}return 'local-'+(h>>>0).toString(16);
}
function monthLabel(month){if(!/^\d{4}-\d{2}$/.test(month))return month;const [y,m]=month.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('es-CO',{month:'long',year:'numeric'})}
function buildMonthlyClose(month){const movements=countedMovements(state.gastos,`${month}-31`).filter(g=>String(g.fecha||'').startsWith(month)),expenses=movements.filter(g=>(g.tipo||'gasto')==='gasto'),incomes=movements.filter(g=>g.tipo==='ingreso'),sum=a=>a.reduce((t,g)=>t+Number(g.monto||0),0),spent=sum(expenses),income=sum(incomes),budget=Number(state.presupuestos?.mensual||0),categories=[...new Set([...state.categories,...Object.keys(state.presupuestos?.categorias||{}),...expenses.map(g=>g.categoria)])].map(c=>{const limit=Number(state.presupuestos?.categorias?.[c]||0),actual=sum(expenses.filter(g=>g.categoria===c));return {categoria:c,presupuesto:limit,gastado:actual,diferencia:limit-actual}}).filter(c=>c.presupuesto>0||c.gastado>0);return {mes:month,etiqueta:monthLabel(month),cerradoEn:new Date().toISOString(),ingresos:income,gastos:spent,saldo:income-spent,presupuesto:budget,diferenciaPresupuesto:budget-spent,porcentajePresupuesto:budget>0?Math.round(spent/budget*100):null,cantidadMovimientos:movements.length,categorias:categories}}
function renderMonthlyClose(){const input=$('#closeMonth');if(!input)return;if(!input.value)input.value=todayISO().slice(0,7);const month=input.value,existing=(state.cierres||[]).find(c=>c.mes===month),close=existing||buildMonthlyClose(month),stats=[['Presupuesto mensual',close.presupuesto?money(close.presupuesto):'Sin definir'],['Gasto real',money(close.gastos)],['Diferencia',close.presupuesto?money(close.diferenciaPresupuesto):'Sin presupuesto'],['Saldo del mes',money(close.saldo)]];$('#monthlyClosePreview').innerHTML=stats.map(([label,value],i)=>`<article class="panel close-stat"><span>${label}</span><strong class="${i===2&&close.diferenciaPresupuesto<0?'negative-value':''}">${value}</strong><small>${i===0?'Límite configurado':i===1?`${close.cantidadMovimientos} movimiento(s)`:i===2?(close.diferenciaPresupuesto<0?'Presupuesto excedido':'Disponible frente al presupuesto'):'Ingresos menos gastos'}</small></article>`).join('');$('#closeCategoryRows').innerHTML=close.categorias.length?close.categorias.map(c=>`<tr><td>${esc(c.categoria)}</td><td class="align-right">${c.presupuesto?money(c.presupuesto):'—'}</td><td class="align-right">${money(c.gastado)}</td><td class="align-right ${c.diferencia<0?'negative-value':'income-value'}">${c.presupuesto?money(c.diferencia):'—'}</td><td><span class="category-chip">${c.presupuesto?(c.gastado>c.presupuesto?'Excedido':'Dentro del límite'):'Sin presupuesto'}</span></td></tr>`).join(''):emptyRow(5,'No hay movimientos ni presupuestos para este mes.');const btn=$('#saveMonthlyClose');btn.textContent=existing?'Actualizar cierre guardado':'Guardar cierre del mes';$('#monthlyCloseHistory').innerHTML=(state.cierres||[]).length?[...state.cierres].sort((a,b)=>b.mes.localeCompare(a.mes)).map(c=>`<article class="close-history-row"><div><b>${esc(c.etiqueta||monthLabel(c.mes))}</b><small>Guardado ${fmtDate((c.cerradoEn||'').slice(0,10))} · ${Number(c.cantidadMovimientos)||0} movimiento(s)</small></div><div class="close-history-values"><span>Gastos <b>${money(c.gastos)}</b></span><span>Presupuesto <b>${Number(c.presupuesto)>0?money(c.presupuesto):'Sin definir'}</b></span><span>Saldo <b class="${c.saldo<0?'negative-value':'income-value'}">${money(c.saldo)}</b></span><button class="btn btn-outline" data-view-close="${esc(c.mes)}">Ver</button></div></article>`).join(''):'<p class="muted-small">Todavía no has guardado cierres mensuales.</p>';}
function saveMonthlyClose(){const input=$('#closeMonth'),month=input.value;if(!/^\d{4}-\d{2}$/.test(month)){toast('Selecciona un mes válido.','error');return}const existing=(state.cierres||[]).find(c=>c.mes===month);if(existing&&!confirm(`Ya existe un cierre de ${monthLabel(month)}. ¿Quieres actualizarlo con los movimientos y presupuestos actuales?`))return;const snapshot=buildMonthlyClose(month);const idx=(state.cierres||[]).findIndex(c=>c.mes===month);if(idx>=0)state.cierres[idx]=snapshot;else state.cierres.push(snapshot);localDB.cierres=state.cierres;persist();renderMonthlyClose();logNotificationAction('Cierre mensual guardado',`Se guardó el resumen de ${snapshot.etiqueta}.`);toast(`Cierre de ${snapshot.etiqueta} guardado correctamente.`)}
function renderProfile(){const saved=JSON.parse(safeGet(AUTH_KEY)||'{}'),name=saved.username||'Usuario';const nameEl=$('#profileUsername'),avatar=$('#profileAvatarLarge'),smallAvatar=$('#profileBtn');if(nameEl)nameEl.textContent=name;if(avatar)avatar.textContent=name.slice(0,2).toUpperCase();if(smallAvatar)smallAvatar.textContent=name.slice(0,2).toUpperCase()}
